import {LEARNING_MAP_PHOTOS} from "../learning-map/photos";
import {ARCH_PHOTOS} from "../classical-architecture/photos";
import {LOCAL_PORTRAITS} from "../roman-portraits";
import {ATLAS_PHOTOS} from "./photos";
import type {AtlasImage} from "./types";

/*
 * A photo for every figure and event that has one, so the atlas is not a list of names.
 *
 * Three kinds of source, all from Wikimedia Commons with their credit and licence:
 * - photos fetched for the atlas itself (photos.ts, generated by tools/fetch_history_atlas_photos.py from
 *   tools/history_atlas_photos.json — finds of prehistory and the Bronze and Iron Ages, pharaohs, inscriptions);
 * - the learning map's site photos and the architecture studio's, which were already chosen and checked by eye
 *   (REUSE below points an atlas item at one of them);
 * - the Roman emperors' portraits.
 * A figure with no portrait of its own may show the place or the find it is known by (Bar Kokhba — the Cave of Letters,
 * Rabban Yochanan ben Zakkai — Yavne); the caption says what the photo shows.
 */
const lm=new Map(LEARNING_MAP_PHOTOS.map(p=>[p.id,p])),arch=new Map(ARCH_PHOTOS.map(p=>[p.id,p]));
const site=(p:{caption:string;alt:string;src:string;author:string;license:string;licenseUrl:string;source:string}):AtlasImage=>
 ({localSrc:"/moreh-derech"+p.src,alt:p.alt,caption:p.caption,sourceUrl:p.source,credit:p.author,license:p.license,licenseUrl:p.licenseUrl});
const roman=(key:string):AtlasImage|undefined=>{const p=LOCAL_PORTRAITS[key];return p&&{localSrc:p.localSrc,alt:p.alt,caption:p.caption,sourceUrl:p.sourceUrl,credit:p.credit,license:p.license,licenseUrl:p.licenseUrl,note:p.note};};

/** Atlas item → "lm:<learning-map photo>", "arch:<architecture photo>", "roman:<portrait>" or "<another atlas item>". */
export const REUSE:Record<string,string>={
 // Figures known by a place or a find
 "L-01":"lm:yavne","L-02":"lm:yavne","L-05":"lm:nahal-hever","L-07":"lm:beit-shearim","L-19":"lm:nativity-grotto",
 "L-22":"lm:euthymius","L-25":"lm:mar-saba","L-27":"lm:gerizim-church","M-06":"lm:masada-northern-palace","P-071":"lm:masada",
 "P-048":"lm:antipatris","P-056":"lm:tower-of-david-tower","P-059":"lm:banias-pan","P-069":"lm:caesarea",
 "P-034":"lm:modiin","P-035":"lm:emmaus","P-012":"arch:tl-alexander","NT-21":"roman:tiberius","P-006":"ST-005",
 "B-03":"BR-09","PH-20":"H-08",
 // Events at sites the site already shows
 "ST-015":"lm:city-of-david","ST-017":"arch:tl-alexander","ST-019":"lm:akko","ST-027":"lm:givati","ST-028":"lm:modiin","ST-031":"lm:emmaus",
 "ST-040":"lm:givati","ST-043":"lm:maresha","ST-049":"arch:tl-pompey","ST-055":"lm:herodium","ST-056":"lm:jericho-palaces-reticulatum",
 "ST-057":"lm:caesarea","ST-058":"lm:temple-mount","ST-059":"lm:antonia","ST-064":"lm:robinson-arch","ST-065":"lm:holy-sepulchre-rotunda",
 "ST-066":"lm:siloam-pool","ST-070":"lm:third-wall","ST-072":"arch:caesarea-theatre","ST-074":"lm:masada","ST-076":"lm:gamla","ST-077":"lm:yodfat",
 "ST-083":"arch:herodian-quarter","ST-084":"lm:binyanei-hauma-stamp","ST-085":"lm:masada-ramp","ST-087":"lm:machaerus",
 "SE-04":"lm:ramat-rachel","SE-06":"lm:hippos","SE-07":"arch:stone-vessels","SE-08":"lm:qumran","SE-09":"lm:alexandrium","SE-10":"lm:avdat","SE-11":"arch:theodotus",
 "RO-020":"lm:yavne","RO-024":"arch:caesarea-hippodrome","RO-026":"lm:mamshit","RO-029":"lm:tel-shalem-hadrian-statue","RO-030":"arch:damascus-gate",
 "RO-031":"lm:nahal-hever","RO-032":"lm:nahal-hever","RO-035":"lm:usha","RO-036":"lm:sepphoris","RO-037":"arch:severus-arch","RO-039":"lm:emmaus","RO-044":"lm:yotvata",
 "BY-003":"arch:nativity","BY-005":"lm:chariton","BY-007":"arch:holy-sepulchre","BY-009":"lm:hamat-tiberias-zodiac","BY-010":"lm:sepphoris","BY-015":"lm:nativity-grotto",
 "BY-019":"arch:capernaum","BY-020":"lm:euthymius","BY-025":"arch:tl-kathisma","BY-026":"lm:mar-saba","BY-027":"lm:gerizim-church","BY-028":"lm:shivta","BY-030":"lm:gerizim",
 "BY-031":"lm:nativity-mosaics","BY-033":"lm:nea","BY-034":"lm:beit-alfa-zodiac","BY-035":"lm:santa-katarina","BY-036":"lm:madaba-jerusalem","BY-037":"lm:rehov-inscription","BY-045":"lm:caesarea",
 "FT-01":"lm:machpelah","FT-06":"lm:city-of-david","FT-20":"lm:lachish","FT-12":"FT-11","FT-13":"FT-14","IR-11":"lm:lachish",
 "BR-03":"B-01","BR-15":"B-04","BR-16":"B-05","BR-22":"BR-08","EC-amarna":"B-06","EC-amenhotep":"F-06",
 // The dimension of Jesus' life and the judges
 "JS-03":"lm:nativity-grotto","JS-13":"lm:capernaum-white-synagogue","JS-15":"lm:machaerus","JS-16":"lm:banias-pan","JS-20":"lm:eleona",
 "JS-22":"arch:tl-holyland","JS-24":"lm:gethsemane","JS-26":"lm:holy-sepulchre-rotunda","JS-27":"arch:holy-sepulchre","JS-28":"lm:magdala",
 "JS-29":"lm:emmaus","JS-31":"lm:tabgha","JS-32":"lm:eleona","JS-38":"lm:caesarea","JD-07":"FT-04","PR-01":"FT-04",
};
function resolve(ref:string,seen=new Set<string>()):AtlasImage|undefined{
 if(ref.startsWith("lm:")){const p=lm.get(ref.slice(3));return p&&site(p);}
 if(ref.startsWith("arch:")){const p=arch.get(ref.slice(5));return p&&site(p);}
 if(ref.startsWith("roman:"))return roman(ref.slice(6));
 if(seen.has(ref))return ATLAS_PHOTOS[ref];
 seen.add(ref);
 return ATLAS_PHOTOS[ref]??(REUSE[ref]&&REUSE[ref]!==ref?resolve(REUSE[ref],seen):undefined);
}
/** The photo of an atlas item, if it has one. */
export const photoOf=(id:string)=>resolve(id);
/** Gives a node the photo it has none of. */
export const withPhoto=<T extends {id:string;image?:AtlasImage}>(n:T):T=>{if(n.image)return n;const image=photoOf(n.id);return image?{...n,image}:n;};
